mapper.select:

WHERE s.del_flag = '0'

    AND s.seal_name LIKE CONCAT('%', #{sealName}, '%')


    AND s.seal_code = #{sealCode}


    AND s.seal_category = #{sealCategory}


    AND s.status = #{status}


    AND s.dept_id = #{deptId}

ORDER BY CAST(SUBSTRING(s.seal_code, 3) AS UNSIGNED) ASC, s.create_time ASC

mapper.update:
UPDATE sign_seal
seal_name = #{sealName}, seal_code = #{sealCode}, seal_category = #{sealCategory}, seal_type = #{sealType}, enable_date = #{enableDate}, org_name = #{orgName}, dept_id = #{deptId}, seal_file_path = #{sealFilePath}, default_size_mm = #{defaultSizeMm}, size_options = #{sizeOptions}, cert_path = #{certPath}, cert_info = #{certInfo}, cert_id = #{certId}, key_ref = #{keyRef}, cert_bind_mode = #{certBindMode}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE seal_id = #{sealId}

mapper.select:

WHERE s.del_flag = '0' AND s.status = '0'

  AND (
      NOT EXISTS (
          SELECT 1 FROM sign_project_seal pps WHERE pps.project_id = #{projectId}
      )
      OR EXISTS (
          SELECT 1
          FROM sign_project_seal pps
          WHERE pps.project_id = #{projectId}
            AND pps.seal_id = s.seal_id
      )
  )


  AND (
      s.dept_id = (SELECT dept_id FROM sys_user WHERE id = #{userId})
      OR s.dept_id IN (
          SELECT id
          FROM sys_dept
          WHERE FIND_IN_SET(
              (SELECT dept_id FROM sys_user WHERE id = #{userId}),
              ancestors
          )
      )
      OR s.seal_id IN (
          SELECT seal_id FROM sign_seal_permission WHERE user_id = #{userId}
      )
  )

ORDER BY CAST(SUBSTRING(s.seal_code, 3) AS UNSIGNED) ASC, s.create_time ASC
